def write(self, data):
    if self._closed:
        raise ValueError('I/O operation on closed storage')

    # Store data in cache
    self.cache = data
    self._cache_modified_count += 1

    # Check if we need to flush the cache
    if self._cache_modified_count >= self.WRITE_CACHE_SIZE:
        self.flush()

