def fragment(self, document: Mapping) -> QueryInstance:
    def test(value):
        for key in document:
            if key not in value or value[key] != document[key]:
                return False

        return True

    return self._generate_test(
        lambda value: test(value),
        ('fragment', freeze(document)),
        allow_empty_path=True
    )

